//! Parity with route.bible: every template value and every desktop link for a set of passages
//! (all 66 books, plus tricky shapes and translations) must match what route.bible's own code
//! produces. Fixture generated by `scripts/route-bible-parity/run <route.bible checkout>`.

use std::collections::BTreeMap;

use bible_core::VerseRef;
use bible_core::books::{BOOKS, BookId};
use bible_core::open_in::{Catalog, Passage, open_url_for};
use bible_core::open_in_context::{normalize_translation, verse_query_text};
use bible_core::open_in_tables::BOOK_VARIANTS;
use bible_core::open_in_translations::TRANSLATION_SUPPORT;
use serde_json::Value;

/// bible-rs puts the verse text in `actionBody` where route.bible (which has no text) sends a link.
const INTENTIONAL: &[&str] = &["actionBody"];

fn passage(canonical: &str) -> Passage {
    let mut parts = canonical.split('.');
    let code = parts.next().unwrap();
    let book = BookId(BOOKS.iter().position(|b| b.code == code).unwrap_or_else(|| panic!("{code}")) as u8);
    let chapter: u8 = parts.next().unwrap().parse().unwrap();
    match parts.next() {
        None => Passage::chapter_only(book, chapter),
        Some(v) => {
            let (a, b) = v.split_once('-').unwrap_or((v, v));
            let (a, b): (u8, u8) = (a.parse().unwrap(), b.parse().unwrap());
            let refs: Vec<VerseRef> = (a..=b).map(|n| VerseRef::new(book, chapter, n)).collect();
            Passage::from_refs(&refs).unwrap()
        }
    }
}

fn cases() -> Vec<Value> {
    let v: Value = serde_json::from_str(include_str!("fixtures/route-bible-parity.json")).unwrap();
    v["cases"].as_array().unwrap().clone()
}

/// Notes are stamped with the capture date; compare everything else.
fn without_date(s: &str) -> String {
    match s.find("date%3A%20%22") {
        Some(i) => format!("{}{}", &s[..i], &s[i + 23..]),
        None => s.to_string(),
    }
}

#[test]
fn book_tables_cover_every_book_in_order() {
    let ours: Vec<&str> = BOOKS.iter().map(|b| b.code).collect();
    let theirs: Vec<&str> = BOOK_VARIANTS.iter().map(|b| b.code).collect();
    assert_eq!(ours, theirs);
}

#[test]
fn template_values_match_route_bible() {
    let mut drift = Vec::new();
    for c in cases() {
        let canonical = c["canonical"].as_str().unwrap();
        let translation = c["translation"].as_str().unwrap();
        let p = passage(canonical);
        assert_eq!(p.canonical(), canonical);
        let ours: BTreeMap<&str, String> = p.template_vars(translation, "");
        for (key, want) in c["vars"].as_object().unwrap() {
            if INTENTIONAL.contains(&key.as_str()) {
                continue;
            }
            let want = without_date(want.as_str().unwrap());
            match ours.get(key.as_str()).map(|s| without_date(s)) {
                Some(got) if got == want => {}
                got => {
                    drift.push(format!("{canonical} {translation} {key}: ours={got:?} route.bible={want:?}"))
                }
            }
        }
    }
    assert!(drift.is_empty(), "{} drifted values:\n{}", drift.len(), drift.join("\n"));
}

#[test]
fn desktop_urls_match_route_bible() {
    let catalog = Catalog::bundled();
    let mut drift = Vec::new();
    let mut checked = 0;
    for c in cases() {
        let canonical = c["canonical"].as_str().unwrap();
        let translation = c["translation"].as_str().unwrap();
        let normalized = normalize_translation(translation);
        let p = passage(canonical);
        for a in catalog.menu_items() {
            let uses_text = a.links.iter().any(|l| l.template.contains("{{actionBody}}"));
            // Sites that don't serve this translation get the untranslated link (tested below).
            let dropped = TRANSLATION_SUPPORT
                .iter()
                .any(|s| s.adapter == a.id && !s.supported.contains(&normalized.as_str()));
            if uses_text || dropped {
                continue;
            }
            let Some(want) = c["urls"].get(&a.id).and_then(Value::as_str) else {
                continue;
            };
            // Books OpenBible has no map for: route.bible disables the adapter there, bible-rs hands
            // off to route.bible's launcher instead of the empty preview page.
            if a.id == "open-bible-geo" && want.ends_with("/geo/preview/") {
                continue;
            }
            // route.bible leaves its own pages relative; bible-rs opens them on route.bible.
            let want =
                if want.starts_with('/') { format!("https://route.bible{want}") } else { want.to_string() };
            let got = open_url_for(p, &a.id, translation, "");
            checked += 1;
            if without_date(&got) != without_date(&want) {
                drift.push(format!("{canonical} {translation} {}: ours={got} route.bible={want}", a.id));
            }
        }
    }
    assert!(checked > 5000, "only {checked} links compared");
    assert!(drift.is_empty(), "{} drifted URLs:\n{}", drift.len(), drift.join("\n"));
}

#[test]
fn unsupported_translation_opens_the_site_default() {
    let jonah = passage("JON.2.3");
    assert_eq!(open_url_for(jonah, "wedevote", "BSB", ""), "https://wd.bible/en/bible/jon.2#3");
    assert_eq!(open_url_for(jonah, "wedevote", "ESV", ""), "https://wd.bible/en/bible/jon.2.esv#3");
    assert_eq!(open_url_for(jonah, "wedevote", "ylt", ""), "https://wd.bible/en/bible/jon.2#3");
    assert_eq!(
        open_url_for(jonah, "blue-letter-bible", "BSB", ""),
        "https://www.blueletterbible.org/jon/2/3/"
    );
    assert_eq!(
        open_url_for(jonah, "blue-letter-bible", "KJV", ""),
        "https://www.blueletterbible.org/kjv/jon/2/3/"
    );
    assert_eq!(
        open_url_for(jonah, "bible-gateway", "BSB", ""),
        "https://www.biblegateway.com/passage/?search=Jonah%202%3A3"
    );
    assert_eq!(
        open_url_for(jonah, "bible-gateway", "WEB", ""),
        "https://www.biblegateway.com/passage/?search=Jonah%202%3A3&version=WEB"
    );
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/route-bible-parity.json")).unwrap()
}

#[test]
fn verse_text_cleanup_matches_route_bible() {
    let v = fixture();
    let cases = v["verseText"].as_array().expect("verseText cases");
    assert!(cases.len() >= 5);
    for c in cases {
        let lines: Vec<&str> = c["input"].as_array().unwrap().iter().map(|l| l.as_str().unwrap()).collect();
        assert_eq!(verse_query_text(&lines.join("\n")), c["output"].as_str().unwrap(), "{lines:?}");
    }
}

#[test]
fn hidden_arrow_searches_the_local_verse_text() {
    let v = fixture();
    let ha = &v["hiddenArrow"];
    let john = passage("JHN.3.16");
    let text = ha["text"].as_str().unwrap();
    let url = open_url_for(john, "hidden-arrow", "KJV", text);
    assert_eq!(url, ha["url"].as_str().unwrap());
    assert!(url.starts_with("https://hiddenarrow.app/?q=For%20God%20so%20loved%20the%20world%2C"));
    // No local text: the reference, as route.bible does.
    assert_eq!(open_url_for(john, "hidden-arrow", "KJV", ""), ha["fallback"].as_str().unwrap());
    assert_eq!(ha["fallback"].as_str().unwrap(), "https://hiddenarrow.app/?q=John%203%3A16");
}
